_V2_PREBOOT_SCRIPT = r'''
Object.assign(state,{globalWorkspace:null,globalChats:[],project:null,projectChats:[],chatScope:null,view:'boot',chatCreateScope:'global'});
const GLOBAL_SENTINEL='__amodex_global_chat_container_v1__';

function uiInstallShell(){
  side.innerHTML=`
    <div class="brand"><div class="brand-main"><span>Amodex</span><span id="statusBadge" class="badge">workspace</span></div><button class="icon-button mobile-side-close" onclick="toggleSide(false)" aria-label="Fechar menu">✕</button></div>
    <button class="item project-launch" onclick="openProjectsHub()"><span class="project-icon">▦</span><span>Projetos</span></button>
    <div class="section global-chat-section">
      <div class="global-chat-header"><h3>Chats</h3><button class="icon-button" onclick="openChatModal('global')" title="Novo chat" aria-label="Novo chat">＋</button></div>
      <div id="globalChatList" class="stack global-chats-scroll"></div>
    </div>
    <div class="side-system"><button class="item" onclick="location.href='/connections'">Conexões</button><button class="item" onclick="location.href='/models'">Modelos</button></div>
    <div class="ui-v2-hidden"><div id="workspaceList"></div><div id="chatList"></div><div id="environmentList"></div></div>`;
  if(!document.getElementById('sideScrim'))document.querySelector('.app').insertAdjacentHTML('afterend','<div id="sideScrim" class="side-scrim" onclick="toggleSide(false)"></div>');

  const shell=document.querySelector('.composer');
  shell.innerHTML=`
    <div id="toolDrawer" class="tool-drawer" aria-hidden="true">
      <button type="button" onclick="uiTool('file')" title="Arquivos" aria-label="Arquivos">📂</button><button type="button" onclick="uiTool('research')" title="Pesquisar na web" aria-label="Pesquisar na web">🌎</button><button type="button" onclick="uiTool('memory')" title="Memória" aria-label="Memória">🧠</button><button type="button" onclick="uiTool('cook')" title="Cozinhar" aria-label="Cozinhar">🍳</button>
    </div>
    <input id="mmFileInput" type="file" multiple hidden onchange="mmFilesSelected(this)"><div id="mmTray" class="mm-tray"></div>
    <div class="composer-row"><button id="toolToggle" class="composer-round" type="button" onclick="uiToggleTools()" aria-label="Ferramentas">＋</button><textarea id="composer" placeholder="Digite aqui…" disabled></textarea><button id="mmMic" class="composer-round" type="button" onclick="mmToggleMic()" aria-label="Falar">🎤</button><button id="uiSend" class="composer-round composer-send" type="button" onclick="sendMessage()" aria-label="Enviar">⏫</button></div>
    <select id="activeEnvironment" class="ui-v2-hidden"><option value="">Sem ambiente</option></select><div id="composerMeta" class="composer-meta"></div>`;
  composer.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendMessage()}});

  const memoryHelp=document.querySelector('#memoryModal p.muted');if(memoryHelp){memoryHelp.className='memory-help';memoryHelp.textContent='Memória guarda decisões e restrições duráveis deste projeto. Ela nasce como candidata e só entra no contexto confiável depois de aprovada.'}
  const draftHelp=document.querySelector('#draftModal p.muted');if(draftHelp){draftHelp.className='cook-help';draftHelp.textContent='Cozinhar organiza o texto sem executar nada: separa novidade de decisões já aprovadas, remove repetição e prepara um draft verificável.'}
}

function toggleSide(force){const open=typeof force==='boolean'?force:!side.classList.contains('open');side.classList.toggle('open',open);document.getElementById('sideScrim')?.classList.toggle('open',open)}
function uiToggleTools(force){const drawer=document.getElementById('toolDrawer');const open=typeof force==='boolean'?force:!drawer.classList.contains('open');drawer.classList.toggle('open',open);drawer.setAttribute('aria-hidden',String(!open));toolToggle.textContent=open?'×':'＋'}
function uiTool(name){uiToggleTools(false);if(name==='file')return typeof mmChooseFiles==='function'?mmChooseFiles():err(new Error('Arquivos ainda não estão prontos'));if(name==='research')return typeof mmResearch==='function'?mmResearch():err(new Error('Pesquisa ainda não está pronta'));if(name==='memory')return openMemoryModal();if(name==='cook')return uiCookDraft()}
function uiSetComposerVisible(visible){document.querySelector('.composer-wrap').classList.toggle('ui-v2-composer-hidden',!visible)}
function uiProjectCountLabel(){return `${state.workspaces.length} projeto${state.workspaces.length===1?'':'s'}`}
function uiHome(){state.view='home';state.chat=null;state.chatScope=null;state.project=null;state.workspace=null;state.messages=[];state.drafts=[];state.memories=[];state.envBindings=[];composer.disabled=true;uiSetComposerVisible(false);chatTitle.textContent='Amodex';workspaceTitle.textContent='Escolha um chat ou abra Projetos';messages.innerHTML='<div class="home-stage"><div><div class="home-logo">A</div><h1>Amodex</h1><p>Selecione um chat na lateral para entrar na conversa, ou abra Projetos para acessar uma pasta de chats.</p><p class="home-hint">Nenhuma conversa é carregada até você escolher uma.</p></div></div>';renderGlobalChats();toggleSide(false)}
function uiChatLoading(title,scope){state.view='chat';chatTitle.textContent=title||'Chat';workspaceTitle.textContent=scope==='global'?'Chat global':(state.project?.name||'Projeto');uiSetComposerVisible(true);composer.disabled=true;messages.innerHTML='<div class="chat-loading"><div class="pulse"></div><div>Carregando conversa…</div></div>';toggleSide(false)}

function renderGlobalChats(){const target=document.getElementById('globalChatList');if(!target)return;target.innerHTML=state.globalChats.length?state.globalChats.map(c=>`<button class="item ${state.chatScope==='global'&&state.chat?.chat_id===c.chat_id?'active':''} ${c.__pending?'optimistic':''}" onclick="selectGlobalChat('${esc(c.chat_id)}')"><strong>${esc(c.title)}</strong><small>${c.__pending?'Criando…':'Chat global'}</small></button>`).join(''):'<div class="muted" style="padding:9px 4px">Nenhum chat.</div>'}
function renderWorkspaces(){if(state.view==='projects')renderProjectsHub();else if(state.view==='project')renderProjectView()}
function renderChats(){renderGlobalChats();if(state.view==='project')renderProjectView()}
function openProjectsHub(){state.view='projects';state.project=null;state.workspace=null;state.chat=null;state.chatScope=null;state.messages=[];state.drafts=[];state.memories=[];state.envBindings=[];composer.disabled=true;uiSetComposerVisible(false);chatTitle.textContent='Projetos';workspaceTitle.textContent=uiProjectCountLabel();renderProjectsHub();renderGlobalChats();toggleSide(false)}
function renderProjectsHub(){if(state.view!=='projects')return;const cards=state.workspaces.length?state.workspaces.map(w=>`<button class="project-card ${w.__pending?'optimistic':''}" onclick="selectWorkspace('${esc(w.workspace_id)}')"><h3>${esc(w.name)}</h3><p>${esc(w.description||'Projeto sem descrição')}</p><div class="folder-meta">${w.__pending?'Criando…':'Abrir pasta de chats →'}</div></button>`).join(''):'<div class="project-empty">Nenhum projeto ainda. Crie o primeiro para separar chats, memória e ambientes.</div>';messages.innerHTML=`<div class="project-hub"><div class="hub-head"><div><h1>Projetos</h1><p>Projetos são pastas: cada um mantém seus chats e contexto próprios.</p></div><button class="primary" onclick="openWorkspaceModal()">＋ Projeto</button></div><div class="project-grid">${cards}</div></div>`}
function renderProjectView(loading=false){if(state.view!=='project'||!state.project)return;const chats=state.projectChats.length?state.projectChats.map(c=>`<button class="project-chat-row ${c.__pending?'optimistic':''}" onclick="selectProjectChat('${esc(c.chat_id)}')"><span><strong>${esc(c.title)}</strong><small>${c.__pending?'Criando…':(c.active_environment_id?'Environment ativo':'Planejamento')}</small></span><span>›</span></button>`).join(''):'<div class="project-empty">Este projeto ainda não tem chats.</div>';messages.innerHTML=`<div class="project-detail"><button class="item project-back" onclick="openProjectsHub()">← Todos os projetos</button><div class="project-detail-head"><div><h1>${esc(state.project.name)}</h1><p>${esc(state.project.description||'Chats e memória exclusivos deste projeto.')}</p></div><button class="primary" onclick="openChatModal('project')">＋ Chat</button></div>${loading?'<div class="chat-loading"><div class="pulse"></div><div>Carregando pasta…</div></div>':`<div class="project-chat-list">${chats}</div>`}</div>`}

async function selectWorkspace(id){const local=state.workspaces.find(w=>w.workspace_id===id);if(!local||local.__pending)return;state.project=local;state.workspace=local;state.projectChats=[];state.view='project';state.chat=null;state.chatScope='project';state.messages=[];state.drafts=[];chatTitle.textContent=local.name;workspaceTitle.textContent='Projeto';composer.disabled=true;uiSetComposerVisible(false);renderProjectView(true);toggleSide(false);try{const snap=await api(`/v1/ui/projects/${id}`);state.project=snap.project;state.workspace=snap.project;state.projectChats=snap.chats||[];state.memories=snap.memories||[];state.envBindings=snap.bindings||[];state.allEnvironments=snap.environments||[];workspaceTitle.textContent=`Projeto · ${state.projectChats.length} chats`;renderProjectView();renderContext();renderGlobalChats()}catch(e){renderProjectView();err(e)}}
async function selectGlobalChat(id){return selectChat(id,'global')}
async function selectProjectChat(id){return selectChat(id,'project')}
async function selectChat(id,forcedScope=null){const globalMatch=state.globalChats.find(c=>c.chat_id===id);const projectMatch=state.projectChats.find(c=>c.chat_id===id);const scope=forcedScope||(globalMatch?'global':'project');const local=scope==='global'?globalMatch:projectMatch;if(!local||local.__pending)return;state.chat=local;state.chatScope=scope;uiChatLoading(local.title,scope);renderGlobalChats();try{const snap=await api(`/v1/ui/chats/${id}`);state.chat=snap.chat;state.workspace=snap.workspace;state.project=scope==='project'?snap.workspace:null;state.messages=snap.messages||[];state.drafts=snap.drafts||[];state.memories=snap.memories||[];state.envBindings=snap.bindings||[];state.allEnvironments=snap.environments||[];state.view='chat';chatTitle.textContent=state.chat.title;workspaceTitle.textContent=scope==='global'?'Chat global':state.workspace.name;composer.disabled=false;composer.readOnly=false;uiSetComposerVisible(true);renderGlobalChats();renderMessages();renderContext();fillEnvironmentSelects();composerMeta.textContent=scope==='global'?'Contexto global':'Contexto: '+state.workspace.name;requestAnimationFrame(()=>{messages.scrollTop=messages.scrollHeight})}catch(e){composer.disabled=true;err(e)}}

function openWorkspaceModal(){openModal('workspaceModal');setTimeout(()=>newWorkspaceName.focus(),20)}
async function createWorkspace(e){e.preventDefault();const name=newWorkspaceName.value.trim();const description=newWorkspaceDescription.value.trim()||null;if(!name)return;const temp={workspace_id:`pending-project-${Date.now()}`,name,description,__pending:true};closeModal('workspaceModal');e.target.reset();state.workspaces.unshift(temp);state.project=temp;state.workspace=temp;state.projectChats=[];state.view='project';state.chat=null;uiSetComposerVisible(false);chatTitle.textContent=name;workspaceTitle.textContent='Criando projeto…';renderProjectView(true);try{const created=await api('/v1/ui/projects',{method:'POST',body:JSON.stringify({name,description})});state.workspaces=state.workspaces.map(w=>w.workspace_id===temp.workspace_id?created:w);state.project=created;state.workspace=created;state.projectChats=[];state.memories=[];state.envBindings=[];state.allEnvironments=[];workspaceTitle.textContent='Projeto · 0 chats';renderProjectView();renderGlobalChats()}catch(x){state.workspaces=state.workspaces.filter(w=>w.workspace_id!==temp.workspace_id);openProjectsHub();err(x)}}
async function openChatModal(scope='global'){state.chatCreateScope=scope;if(scope==='project'&&!state.project)return err(new Error('Abra um projeto primeiro'));if(scope==='project'){state.workspace=state.project;fillEnvironmentSelects()}else{newChatEnvironment.innerHTML='<option value="">Nenhum</option>'}openModal('chatModal');setTimeout(()=>newChatTitle.focus(),20)}
async function createChat(e){e.preventDefault();const title=newChatTitle.value.trim();if(!title)return;const scope=state.chatCreateScope||'global';const env=scope==='project'?(newChatEnvironment.value||null):null;const temp={chat_id:`pending-chat-${Date.now()}`,title,active_environment_id:env,__pending:true};closeModal('chatModal');e.target.reset();if(scope==='global')state.globalChats.unshift(temp);else state.projectChats.unshift(temp);state.chat=temp;state.chatScope=scope;uiChatLoading(title,scope);renderGlobalChats();try{const path=scope==='global'?'/v1/ui/global-chats':`/v1/ui/projects/${state.project.workspace_id}/chats`;const created=await api(path,{method:'POST',body:JSON.stringify({title,active_environment_id:env})});if(scope==='global')state.globalChats=state.globalChats.map(c=>c.chat_id===temp.chat_id?created:c);else state.projectChats=state.projectChats.map(c=>c.chat_id===temp.chat_id?created:c);state.chat=created;state.messages=[];state.drafts=[];state.view='chat';chatTitle.textContent=created.title;workspaceTitle.textContent=scope==='global'?'Chat global':state.project.name;composer.disabled=false;uiSetComposerVisible(true);renderGlobalChats();renderMessages();composerMeta.textContent=scope==='global'?'Contexto global':'Contexto: '+state.project.name;if(scope==='global'){api(`/v1/ui/chats/${created.chat_id}`).then(s=>{state.workspace=s.workspace;state.memories=s.memories||[];state.envBindings=s.bindings||[];state.allEnvironments=s.environments||[];renderContext();fillEnvironmentSelects()}).catch(console.warn)}}catch(x){if(scope==='global')state.globalChats=state.globalChats.filter(c=>c.chat_id!==temp.chat_id);else state.projectChats=state.projectChats.filter(c=>c.chat_id!==temp.chat_id);scope==='project'?(state.view='project',state.chat=null,renderProjectView()):uiHome();err(x)}}

function uiUnits(text){return text.replace(/([.!?])\s+/g,'$1\n').split(/\n+/).map(x=>x.trim()).filter(Boolean)}
function uiNorm(text){return text.toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim()}
function uiSimilarity(a,b){const A=new Set(uiNorm(a).split(' ').filter(x=>x.length>2)),B=new Set(uiNorm(b).split(' ').filter(x=>x.length>2));if(!A.size||!B.size)return 0;let hit=0;A.forEach(x=>{if(B.has(x))hit++});return hit/Math.max(A.size,B.size)}
function uiCookDraft(){if(!state.chat)return err(new Error('Abra um chat antes de cozinhar'));const text=composer.value.trim();if(!text)return err(new Error('Digite a ideia ou tarefa que deseja cozinhar'));const ideas=[...new Set(uiUnits(text))];const approved=state.memories.filter(m=>m.status==='APPROVED').map(m=>m.content);const previous=state.messages.filter(m=>m.role==='OWNER').slice(-30).map(m=>m.content);const known=[...approved,...previous],repeated=[],fresh=[];for(const idea of ideas){(known.some(old=>uiSimilarity(idea,old)>=.72)?repeated:fresh).push(idea)}const objective=(fresh[0]||ideas[0]||text).slice(0,100000);const freshBody=(fresh.length?fresh:ideas).map(x=>'• '+x).join('\n');const knownBody=repeated.length?`\n\nJÁ DECIDIDO — NÃO REABRIR SEM CONFLITO NOVO:\n${repeated.map(x=>'• '+x).join('\n')}`:'';draftTitle.value=(fresh[0]||ideas[0]||'Tarefa preparada').slice(0,200);draftObjective.value=objective;draftInstructions.value=`NOVO / EXECUTAR:\n${freshBody}${knownBody}\n\nDISCIPLINA:\n• Preservar decisões aprovadas e arquitetura estável.\n• Não repetir investigação já resolvida sem evidência nova.\n• Se houver bloqueio, apontar o bloqueio concreto e a menor mudança necessária.`;draftValidation.value='Validar somente as mudanças novas; confirmar ausência de regressão; comparar com memórias aprovadas e relatar evidência objetiva.';fillEnvironmentSelects();openModal('draftModal')}

boot=async function(){uiInstallShell();uiHome();try{const snap=await api('/v1/ui/bootstrap');statusBadge.textContent=snap.ready?'ready':'not ready';inferenceBadge.textContent=snap.chat_inference==='GATED_BENCHMARK_PENDING'?'AI gated':'AI';state.globalWorkspace=snap.global_workspace;state.globalChats=snap.global_chats||[];state.workspaces=snap.projects||[];state.allEnvironments=[];renderGlobalChats();workspaceTitle.textContent='Escolha um chat ou abra Projetos'}catch(e){err(e)}};
'''


def augment_workspace_v2_html(html: str) -> str:
    """Install the V2 UX without changing durable workspace API contracts."""
    result = html.replace("</style>", _V2_CSS + "</style>", 1)
    marker = "boot();\n</script>"
    if marker not in result:
        raise ValueError("workspace V2 boot marker not found")
    return result.replace(marker, _V2_PREBOOT_SCRIPT + "\nboot();\n</script>", 1)
